    public static CustomerFilter of(String name, Set<CustomerStatus> statuses) {
        return new CustomerFilter(Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS)
                .splitAsStream(fold(name)).filter(term -> !term.isEmpty()).toList(), statuses);
